package com.voicetxt.reader;

import android.app.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.text.TextUtils;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Bottom sheet voice chooser with real available voices and persistent selection. */
final class VoicePicker extends Dialog {
    static class Item {final String key,title,subtitle,avatar;final int tab;Item(String k,String t,String s,String a,int bucket){key=k;title=t;subtitle=s;avatar=a;tab=bucket;}}
    interface Host {List<Item> items();String selectedKey();void select(Item item);void preview(Item item);default List<String> languages(){return Collections.emptyList();}default String language(){return "";}default void language(String code){}}
    String previewKey="";final HashMap<String,TextView> previewIcons=new HashMap<>();final HashMap<String,View> previewButtons=new HashMap<>();final HashMap<String,String> previewTitles=new HashMap<>();
    final Activity activity;final Host host;final boolean night;final int red=0xffdf382c,gold=0xffd6a14c;
    LinearLayout panel,grid,languageBar;HorizontalScrollView languageScroll;TextView section,current;ScrollView scroll;final ArrayList<TextView> tabs=new ArrayList<>();final ArrayList<View> lines=new ArrayList<>();int tab=0;boolean autoTab=true;
    VoicePicker(Activity a,boolean dark,Host h){super(a);activity=a;night=dark;host=h;for(Item item:h.items())if(item.key.equals(h.selectedKey()))tab=item.tab;}
    int dp(float n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    int ink(){return night?0xffeeeeee:0xff292929;}
    TextView text(String value,int size,int color){TextView t=new TextView(activity);t.setText(value);t.setTextSize(size);t.setTextColor(color);return t;}
    GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    @Override protected void onCreate(Bundle saved){super.onCreate(saved);panel=new LinearLayout(activity);panel.setOrientation(1);GradientDrawable background=shape(night?0xff24262d:Color.WHITE,0);background.setCornerRadii(new float[]{dp(18),dp(18),dp(18),dp(18),0,0,0,0});panel.setBackground(background);panel.setClipToOutline(true);setContentView(panel);
        panel.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(0,0,0,insets.getSystemWindowInsetBottom());return insets;});
        LinearLayout header=new LinearLayout(activity);panel.addView(header,new LinearLayout.LayoutParams(-1,dp(56)));
        TextView title=text(activity.getString(R.string.vp_title),19,ink());title.setTypeface(null,Typeface.BOLD);title.setGravity(Gravity.CENTER);header.addView(title,new LinearLayout.LayoutParams(-1,-1));
        View divider=new View(activity);divider.setBackgroundColor(night?0xff393b42:0xffeeeeee);panel.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));
        languageScroll=new HorizontalScrollView(activity);languageScroll.setHorizontalScrollBarEnabled(false);languageBar=new LinearLayout(activity);languageBar.setGravity(Gravity.CENTER_VERTICAL);languageBar.setPadding(dp(16),dp(10),dp(16),dp(4));languageScroll.addView(languageBar);panel.addView(languageScroll,new LinearLayout.LayoutParams(-1,-2));
        section=text("",16,ink());section.setPadding(dp(20),0,dp(20),0);section.setGravity(Gravity.CENTER_VERTICAL);panel.addView(section,new LinearLayout.LayoutParams(-1,dp(46)));
        scroll=new ScrollView(activity);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));grid=new LinearLayout(activity);grid.setOrientation(1);grid.setPadding(dp(12),dp(4),dp(12),dp(12));scroll.addView(grid);
        current=text("",12,night?0xffb4b4bb:0xff888888);current.setGravity(Gravity.CENTER);current.setMaxLines(2);current.setEllipsize(TextUtils.TruncateAt.END);current.setPadding(dp(16),0,dp(16),0);panel.addView(current,new LinearLayout.LayoutParams(-1,dp(42)));
        View rule=new View(activity);rule.setBackgroundColor(night?0xff393b42:0xffeeeeee);panel.addView(rule,new LinearLayout.LayoutParams(-1,dp(1)));TextView close=text(activity.getString(R.string.ui_11),18,ink());close.setGravity(Gravity.CENTER);close.setContentDescription(activity.getString(R.string.ui_204));panel.addView(close,new LinearLayout.LayoutParams(-1,dp(54)));close.setOnClickListener(v->dismiss());refresh();
        Window window=getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setGravity(Gravity.BOTTOM);window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);window.setDimAmount(.4f);window.setNavigationBarColor(night?0xff24262d:Color.WHITE);}
    }
    @Override public void show(){super.show();Window w=getWindow();if(w!=null){int height=activity.getResources().getDisplayMetrics().heightPixels;w.setLayout(-1,Math.round(height*.66f));}panel.setTranslationY(dp(36));panel.setAlpha(0);panel.animate().translationY(0).alpha(1).setDuration(220).start();panel.requestApplyInsets();}
    void refresh(){if(grid==null)return;List<String> languages=host.languages();languageScroll.setVisibility(languages.isEmpty()?View.GONE:View.VISIBLE);languageBar.removeAllViews();for(String code:languages){boolean active=code.equals(host.language());TextView chip=text(VoiceLanguages.name(code,AppLanguage.locale(activity)),13,active?red:ink());chip.setGravity(Gravity.CENTER);chip.setPadding(dp(16),0,dp(16),0);chip.setBackground(shape(active?(night?0xff503039:0xffffe9e4):(night?0xff343740:0xfff3f4f6),22));chip.setSelected(active);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-2,dp(44));cp.setMarginEnd(dp(8));languageBar.addView(chip,cp);chip.setOnClickListener(v->{host.language(code);refresh();});if(active)languageScroll.post(()->languageScroll.smoothScrollTo(Math.max(0,chip.getLeft()-dp(16)),0));}List<Item> available=host.items();section.setText(activity.getString(languages.isEmpty()?R.string.voice_language_filter:R.string.vp_original_voice_hint));grid.removeAllViews();previewIcons.clear();previewButtons.clear();previewTitles.clear();ArrayList<Item> visible=new ArrayList<>();String selected=host.selectedKey();String selection="";for(Item item:available){visible.add(item);if(item.key.equals(selected))selection=item.title;}current.setText(activity.getString(R.string.voice_hint,selection));
        if(visible.isEmpty()){TextView empty=text(activity.getString(R.string.voice_language_missing),15,0xff999999);empty.setGravity(Gravity.CENTER);grid.addView(empty,new LinearLayout.LayoutParams(-1,dp(150)));return;}
        for(int i=0;i<visible.size();i+=3){LinearLayout row=new LinearLayout(activity);row.setGravity(Gravity.TOP);grid.addView(row);for(int col=0;col<3;col++){LinearLayout card=new LinearLayout(activity);card.setOrientation(1);card.setGravity(Gravity.CENTER_HORIZONTAL);card.setPadding(dp(4),dp(8),dp(4),dp(12));row.addView(card,new LinearLayout.LayoutParams(0,dp(180),1));if(i+col>=visible.size())continue;Item item=visible.get(i+col);boolean chosen=item.key.equals(selected);
            FrameLayout portrait=new FrameLayout(activity);GradientDrawable border=shape(Color.TRANSPARENT,40);if(chosen)border.setStroke(dp(2),gold);portrait.setBackground(border);portrait.setPadding(dp(4),dp(4),dp(4),dp(4));card.addView(portrait,new LinearLayout.LayoutParams(dp(72),dp(72)));ImageView image=new ImageView(activity);GradientDrawable circle=shape(0xffdcebe6,40);image.setBackground(circle);image.setClipToOutline(true);image.setScaleType(ImageView.ScaleType.CENTER_CROP);int res=activity.getResources().getIdentifier(item.avatar,"drawable",activity.getPackageName());image.setImageResource(res);FrameLayout.LayoutParams imageLp=new FrameLayout.LayoutParams(-1,-1);portrait.addView(image,imageLp);FrameLayout previewArea=new FrameLayout(activity);previewArea.setContentDescription(activity.getString(R.string.ui_211)+item.title);FrameLayout.LayoutParams hit=new FrameLayout.LayoutParams(dp(48),dp(48),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);portrait.addView(previewArea,hit);TextView play=text("▶",14,Color.WHITE);play.setGravity(Gravity.CENTER);play.setPadding(dp(2),0,0,0);play.setBackground(shape(0xdd333333,20));play.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);FrameLayout.LayoutParams circleLp=new FrameLayout.LayoutParams(dp(30),dp(30),Gravity.CENTER);previewArea.addView(play,circleLp);previewIcons.put(item.key,play);previewButtons.put(item.key,previewArea);previewTitles.put(item.key,item.title);updatePreviewButton(item.key);previewArea.setOnClickListener(v->host.preview(item));if(chosen){TextView tick=text("✓",16,Color.WHITE);tick.setGravity(Gravity.CENTER);tick.setBackground(shape(gold,5));tick.setContentDescription(activity.getString(R.string.ui_212));tick.setOnClickListener(v->{host.select(item);refresh();});FrameLayout.LayoutParams mark=new FrameLayout.LayoutParams(dp(22),dp(22),Gravity.BOTTOM|Gravity.END);portrait.addView(tick,mark);}
            TextView name=text(item.title,14,chosen?red:ink());name.setGravity(Gravity.CENTER);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);LinearLayout.LayoutParams titleLp=new LinearLayout.LayoutParams(-1,dp(38));titleLp.topMargin=dp(4);card.addView(name,titleLp);TextView desc=text(item.subtitle,11,0xff999999);desc.setGravity(Gravity.CENTER);desc.setMaxLines(2);desc.setEllipsize(TextUtils.TruncateAt.END);card.addView(desc,new LinearLayout.LayoutParams(-1,dp(34)));card.setSelected(chosen);card.setContentDescription(activity.getString(R.string.ui_213)+item.title);card.setOnClickListener(v->{host.select(item);refresh();});}}
    }
    void setPreviewKey(String key){previewKey=key;for(String itemKey:previewIcons.keySet())updatePreviewButton(itemKey);}
    void updatePreviewButton(String key){boolean active=key.equals(previewKey);TextView icon=previewIcons.get(key);if(icon!=null){icon.setText(active?"Ⅱ":"▶");icon.setBackground(shape(active?red:0xdd333333,20));}View button=previewButtons.get(key);if(button!=null)button.setContentDescription((active?activity.getString(R.string.ui_214):activity.getString(R.string.ui_211))+previewTitles.get(key));}

}
